import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.StringTokenizer

lateinit var matrix: Array<IntArray>
var m: Long = 0
var mod: Long = 1000000007

fun multiply(one: Array<IntArray>, two: Array<IntArray>): Array<IntArray> {
    val mi = m.toInt()
    val res = Array(mi) { IntArray(mi) }
    for (i in 0 until mi) {
        for (j in 0 until mi) {
            for (k in 0 until mi) {
                res[i][j] += (one[i][k].toLong() * two[k][j].toLong() % mod).toInt()
                res[i][j] %= mod.toInt()
            }
        }
    }
    return res
}

fun power(exp: Long, base: Array<IntArray>): Array<IntArray> {
    if (exp == 1L) return base

    var res = power(exp / 2, base)
    res = multiply(res, res)
    if (exp and 1L == 1L) {
        res = multiply(res, base)
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val pw = PrintWriter(System.`out`)

    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toLong()
    m = st.nextToken().toLong()

    if (n < m) {
        pw.print("1")
        pw.flush()
        return
    }
    if (n == m) {
        pw.print("2")
        pw.flush()
        return
    }

    val mi = m.toInt()
    matrix = Array(mi) { IntArray(mi) }
    matrix[0][0] = 1
    matrix[0][mi - 1] = 1
    for (i in 1 until mi) {
        matrix[i][i - 1] = 1
    }

    val result = power(n, matrix)
    pw.println(result[0][0])
    pw.flush()
}
